(7668501, 1251301, 251681, '<td valign="top">Depressing sign for those who have children bored at home. Very simple, effective composition. Did you saturate the colors?</td>', 'Depressing sign for those who have children bored at home. Very simple, effective composition. Did you saturate the colors?', '2020-07-01 23:36:55.000000', NULL, 1),
